def F(term,meaning,case,error,why): return dict(term=term,meaning=meaning,case=case,error=error,why=why)
def item(q,r,wrong,why):
    assert len(wrong)==3
    return dict(q=q,r=r,w=[x[0] for x in wrong],e=[x[1] for x in wrong],y=why)
def qa(n,key,level,items): return B.QA(f"e4-{n}-{key}",level,"{X.q}",items,SRC)
def choose(n,rows,level=2,key="apply"):
    return qa(n,key,level,[item(q,r,list(zip(w,e)),why) for q,r,w,e,why in rows])
def word_order(n,sentences): return B.WO(f"e4-{n}-build",2,sentences,SRC)

def unit(n,title,goal,back,next_use,note,case,method,facts,applied,prereq=(),paper=None,extra=None,example=None):
    assert 4 <= len(facts) <= 6
    terms=[]; cases=[]
    for i,f in enumerate(facts):
        other=[x for j,x in enumerate(facts) if j!=i][:3]
        terms.append(item("Which term means "+f["meaning"]+"?",f["term"],[(x["term"],"That concerns "+x["meaning"]+", rather than "+f["meaning"]+".") for x in other],f["why"]))
        cases.append(item(f["case"]+"\nWhich description best fits the selected feature?",f["term"],[(x["term"],"That means "+x["meaning"]+". The selected feature instead illustrates "+f["meaning"]+".") for x in other],f["why"]))
    q0=qa(n,"terms",1,terms); q1=qa(n,"cases",1,cases)
    q3=extra or B.MT(f"e4-{n}-link",2,"Match each term to its example.",[(f["term"],f["case"]) for f in facts],SRC,pick=3)
    q4=B.SP(f"e4-{n}-repair",3,"Find the incorrect claim or language form.",[f["term"]+": "+f["meaning"]+"." for f in facts],[(f["error"],f["why"]) for f in facts],SRC)
    for st,f in zip(q4["pool"]["right"],facts): st["explain"]="This is correct: "+f["meaning"]+". Look for a claim that conflicts with a rule or distinction taught in Learn."
    questions=[q0,q1,applied,q3,q4]
    cards=[card(f"e4-{n}-c1","Distinguish the ideas used in this lesson.",[f["term"]+": "+f["meaning"]+"." for f in facts],q0["id"]),
       card(f"e4-{n}-c2","Read the whole example before identifying its function.",[f["case"] for f in facts],q1["id"]),
       card(f"e4-{n}-c3","A correction must preserve the intended meaning and form.",[f["error"]+" Correction: "+f["why"] for f in facts],q4["id"])]
    L.lesson("english","english-language",n,(f"e4-{n}",title),prereq,note,
       example or worked({},facts[0]["case"]+" Explain the selected feature.",[facts[0]["meaning"].capitalize()+".",facts[0]["why"]],facts[0]["term"]),cards,questions,paper=paper,
       learn=learn([("Your goal and connections","By the end, you should be able to "+goal+". Builds on: "+back+". Leads to: "+next_use+"."),
         ("Understand the pattern",note),("Read the original model",case),("Apply and check",method)],
         key_words=[(f["term"],f["meaning"]) for f in facts],mistake=(facts[0]["error"],facts[0]["term"]+": "+facts[0]["meaning"]+".",facts[0]["why"])))
    PATH.append((n,title,goal,back,next_use))

def writing(n,title,goal,back,next_use,note,model,method,facts,prompt,checks,prereq=()):
    unit(n,title,goal,back,next_use,note,"Original model: "+model,method,facts,
       word_order(n,["A clear purpose guides the response.","The audience shapes the language.","Supporting details develop the main idea.","A final check improves the draft."]),prereq,
       paper=dict(vars={},checks=[],prompt=prompt,model=[model],checklist=checks))

# Core grammar: concrete completion/repair banks, not only terminology questions.
unit(3,"Parts of speech and a tense overview","identify word functions in context and distinguish common tense/aspect patterns",
 "Form Three’s sentence patterns and verb forms","choosing accurate simple forms, clause patterns and narrative tenses",
 "A word’s class depends on its use: book is a noun in the book and a verb in book a room. Nouns name, verbs form the clause’s action or state, adjectives describe nouns and adverbs can modify actions or other expressions. Time and grammatical tense are related but not identical. Simple present often expresses habits; simple past presents completed past events. Progressive forms use be + -ing; perfect forms use have + past participle. This is an overview, not a claim that every form has only one meaning.",
 "Original capsule: Bih reads after chores: present habit. Yesterday she {past('write')} a note: simple past. She is {ing('read')} now: present progressive. She has {participle('write')} the note: present perfect. By the later meeting she had {participle('write')} it: past perfect. She will read tomorrow: future reference. Read the whole time context before choosing a form.",
 "Ask what the word does in this sentence, then identify the finite verb and any auxiliary. Do not label every -ly word an adverb without checking its function. A past participle is not automatically the same as the simple past. Later lessons practise particular contrasts in more depth.",[
 F("noun","a word naming an entity or idea in the stated use","In the book is here, book names an object.","Book must be a verb in every sentence.","Word class depends on use; the book uses book as a noun."),F("verb","a word functioning in the clause’s action or state pattern","In book a room, book expresses the action.","A word’s spelling fixes one class in every use.","The same spelling can have a different grammatical function."),F("adjective","a word describing a noun in the stated pattern","In a quiet room, quiet describes room.","Quiet in a quiet room modifies only a verb.","It describes the noun room, so it is adjectival here."),F("adverb","a word modifying how or when an action occurs in the stated pattern","In Bih reads quietly, quietly modifies reads.","Every adjective and adverb can be exchanged without changing the construction.","Choose the form that fits what it modifies.")],
 choose(3,[("Choose the action in progress now.","Bih is reading now.",["Bih reading now.","Bih is read now.","Bih has read yesterday."],["A finite auxiliary is missing.","The progressive needs -ing after be.","This combines present perfect with a definite past time and does not give the requested progressive."],"Be plus -ing gives the stated action in progress."),
 ("Choose the complete present-perfect pattern.","Ayuk has written the note.",["Ayuk has wrote the note.","Ayuk have written the note.","Ayuk written the note."],["Use the participle written after has.","A singular third-person subject takes has.","The finite auxiliary is missing."],"Use has + past participle with this subject."),
 ("Which word is an adjective in a careful learner?","careful",["learner","a","carefully"],["Learner is the noun being described.","A is a determiner.","Carefully is not the adjective used in this phrase."],"Careful describes the noun learner."),
 ("Choose the completed past event.","Bih wrote yesterday.",["Bih writes yesterday.","Bih writing yesterday.","Bih has wrote yesterday."],["The simple-present form does not fit this completed-event model.","A finite verb is missing.","Use the past wrote here, not has plus wrote."],"The definite completed past context uses the simple past.")]))

